from __future__ import annotations
import cmath, math
from itertools import product
Matrix=tuple[tuple[complex,complex],tuple[complex,complex]]
def mm(a:Matrix,b:Matrix)->Matrix:
 return tuple(tuple(sum(a[i][k]*b[k][j] for k in range(2)) for j in range(2)) for i in range(2)) # type: ignore
def dist(a:Matrix,b:Matrix)->float:
 return math.sqrt(sum(abs(a[i][j]-b[i][j])**2 for i in range(2) for j in range(2)))
phi=(1+math.sqrt(5))/2; q=math.sqrt(1/phi)
F=((1/phi,q),(q,-1/phi)); R=((cmath.exp(-4j*math.pi/5),0j),(0j,cmath.exp(3j*math.pi/5)))
S=mm(mm(F,R),F); I=((1+0j,0j),(0j,1+0j)); target=((0j,1+0j),(1+0j,0j))
best=(dist(I,target),())
for length in range(1,9):
 for word in product((0,1),repeat=length):
  gate=I
  for letter in word: gate=mm(gate,(R,S)[letter])
  best=min(best,(dist(gate,target),word))
print("best Frobenius distance and positive word:",best)

