from collections.abc import Callable
Matrix=tuple[tuple[complex,complex],tuple[complex,complex]]
def multiply(a:Matrix,b:Matrix)->Matrix:
 return tuple(tuple(sum(a[i][k]*b[k][j] for k in range(2)) for j in range(2)) for i in range(2)) # type: ignore
def nearest(target:Matrix,gates:dict[int,Matrix],limit:int,distance:Callable[[Matrix,Matrix],float])->tuple[list[int],float]:
 identity:Matrix=((1+0j,0j),(0j,1+0j)); best=([],distance(identity,target)); frontier=[([],identity)]
 for _ in range(limit):
  nxt=[]
  for word,value in frontier:
   for letter,gate in gates.items():
    if word and letter == -word[-1]: continue
    candidate=multiply(value,gate); trial=distance(candidate,target)
    if trial<best[1]: best=(word+[letter],trial)
    nxt.append((word+[letter],candidate))
  frontier=nxt
 return best

